import{_ as n,a0 as a,w as r,s as g,ao as p,I as t,a1 as l,A as s,x as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Kali Linux 中安装 Google Chrome 浏览器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kali Linux 中安装 Google Chrome 浏览器 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kali Linux 中安装 Google Chrome 浏览器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kali Linux 中安装 Google Chrome 浏览器 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170121 How to install Google Chrome Browser on Kali Linux","title":"如何在 Kali Linux 中安装 Google Chrome 浏览器","tag":"201702","desc":""},"relativePath":"201702/20170121 How to install Google Chrome Browser on Kali Linux.md","filePath":"[post].md"}'),d={name:"201702/20170121 How to install Google Chrome Browser on Kali Linux.md"};function h(u,e,m,c,b,k){const i=a("Link");return r(),g("div",null,[e[15]||(e[15]=p(`<h1 id="如何在-kali-linux-中安装-google-chrome-浏览器" tabindex="-1">如何在 Kali Linux 中安装 Google Chrome 浏览器 <a class="header-anchor" href="#如何在-kali-linux-中安装-google-chrome-浏览器" aria-label="Permalink to “如何在 Kali Linux 中安装 Google Chrome 浏览器”">​</a></h1><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p><strong>目的</strong></p><p>我们的目标就是在 Kali Linux 上安装好 Google Chrome Web 浏览器。同时，请参阅附录为可能出现的问题进行排查。</p><p><strong>要求</strong></p><p>需要获得已安装 Kali Linux 或者 Live 系统的特权。</p><p><strong>困难程度</strong></p><p>容易。</p><p><strong>惯例</strong></p><ul><li><code>#</code> - 给定命令需要以 root 用户权限运行或者使用 <code>sudo</code> 命令</li><li><code>$</code> - 给定命令以常规权限用户运行</li></ul><h3 id="步骤说明" tabindex="-1">步骤说明 <a class="header-anchor" href="#步骤说明" aria-label="Permalink to “步骤说明”">​</a></h3><p><strong>下载 Google Chrome</strong></p><p>首先，使用 <code>wget</code> 命令来下载最新版本的 Google Chrome 的 debian 安装包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># wget https://dl.google.com/linux/direct/google-chrome-stable_current_amd64.deb</span></span></code></pre></div><p><strong>安装 Google Chrome</strong></p><p>在 Kali Linux 安装 Google Chrome 最容易的方法就是使用 <code>gdebi</code>，它会自动帮你下载所有的依赖包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># gdebi google-chrome-stable_current_amd64.deb</span></span></code></pre></div><p><strong>启动 Google Chrome</strong></p><p>开启一个终端（terminal），执行 <code>google-chrome</code> 命令来启动 Google Chrome 浏览器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ google-chrome</span></span></code></pre></div><h3 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to “附录”">​</a></h3><p><strong>非法指令 (Illegal Instruction)</strong></p><p>当以 root 用户特权来运行 <code>google-chrome</code> 命令是，会出现 非法指令 (Illegal Instruction) 错误信息。因为通常情况下，Kali Linux 默认情况下的默认用户是 root 用户，我们需要创建一个虚的非特权用户，比如 <code>linuxconfig</code>，然后使用这个用户来启动 Google Chrome 浏览器。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd -m -d /home/linuxconfig linuxconfig</span></span>
<span class="line"><span># su linuxconfig -c google-chrome</span></span></code></pre></div><p><strong>libappindicator1 包未安装</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dpkg: dependency problems prevent configuration of google-chrome-stable:</span></span>
<span class="line"><span> google-chrome-stable depends on libappindicator1; however:</span></span>
<span class="line"><span>  Package libappindicator1 is not installed.</span></span></code></pre></div><p>使用 <code>gdebi</code> 命令来安装 Google Chrome 的 debian 包可以解决依赖问题。参阅上文。</p><p><img src="https://linuxconfig.org/images/kali-linux-google-chome-browser-start.jpg" alt="在 Kali Linux 中以普通用户启动 google chrome"></p><hr><p>译者简介：</p>`,30)),t("p",null,[l(i,{href:"http://GHLandy.com"},{default:s(()=>[...e[0]||(e[0]=[o("GHLandy",-1)])]),_:1}),e[1]||(e[1]=o(" —— 生活中所有欢乐与苦闷都应藏在心中，有些事儿注定无人知晓，自己也无从说起。",-1))]),e[16]||(e[16]=t("hr",null,null,-1)),t("p",null,[e[3]||(e[3]=o("via: ",-1)),l(i,{href:"https://linuxconfig.org/how-to-install-google-chrome-browser-on-kali-linux"},{default:s(()=>[...e[2]||(e[2]=[o("https://linuxconfig.org/how-to-install-google-chrome-browser-on-kali-linux",-1)])]),_:1})]),t("p",null,[e[7]||(e[7]=o("作者：",-1)),l(i,{href:"https://linuxconfig.org/how-to-install-google-chrome-browser-on-kali-linux"},{default:s(()=>[...e[4]||(e[4]=[o("Lubos Rendek",-1)])]),_:1}),e[8]||(e[8]=o(" 译者：",-1)),l(i,{href:"https://github.com/GHLandy"},{default:s(()=>[...e[5]||(e[5]=[o("GHLandy",-1)])]),_:1}),e[9]||(e[9]=o(" 校对：",-1)),l(i,{href:"https://github.com/wxy"},{default:s(()=>[...e[6]||(e[6]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=o("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[10]||(e[10]=[o("LCTT",-1)])]),_:1}),e[13]||(e[13]=o(" 原创编译，",-1)),l(i,{href:"https://linux.cn/"},{default:s(()=>[...e[11]||(e[11]=[o("Linux中国",-1)])]),_:1}),e[14]||(e[14]=o(" 荣誉推出",-1))])])}const L=n(d,[["render",h]]);export{C as __pageData,L as default};
